def implies(p, q):
    return (not p) or q

rows = [(p, q, implies(p, q)) for p in (False, True) for q in (False, True)]
assert [r for r in rows if not r[2]] == [(True, False, False)]
assert all(implies(p, q) == ((not p) or q) for p, q, _ in rows)
mp = [(p, q) for p in (False, True) for q in (False, True) if p and implies(p, q)]
assert mp == [(True, True)]

def chain(p, q, r):
    return implies(p, q) and implies(q, r)

sat = [(p, q, r) for p in (0, 1) for q in (0, 1) for r in (0, 1) if chain(bool(p), bool(q), bool(r))]
assert sat == [(0, 0, 0), (0, 0, 1), (0, 1, 1), (1, 1, 1)]
assert all((not p) or r for p, q, r in sat)
assert not all(r for p, q, r in sat)

def resolve(c1, c2):
    for lit in c1:
        neg = lit[1:] if lit.startswith("~") else "~" + lit
        if neg in c2:
            return (c1 - {lit}) | (c2 - {neg})
    return None

assert resolve({"~P", "Q"}, {"P"}) == {"Q"}
assert resolve({"~Q", "R"}, {"Q"}) == {"R"}
count = sum((p or q or r) and not (p and q and r) for p in (0, 1) for q in (0, 1) for r in (0, 1))
assert count == 6
print(len(sat), count)
